// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
        // initialize via low-level call (interface types unavailable here);
        // glpManager is a helper exposing vault(), as init reads glpManager.vault()
        VaultHelper g = new VaultHelper();
        address(c).call(
            abi.encodeWithSignature(
                "initialize(address,address,address,address,address,address)",
                address(1), address(2), address(3), address(g), address(4), address(this)
            )
        );
    }

    function testFuzz_property(address actorA, address actorB) public {
        vm.assume(actorA != address(0) && actorB != address(0));
        vm.assume(actorA != actorB);

        vm.prank(actorA);
        address oA = c.owner();
        vm.prank(actorB);
        address oB = c.owner();

        // owner() must be caller-independent: same value for every caller
        assertTrue(oA == oB);
    }
}

contract VaultHelper {
    function vault() external pure returns (address) {
        return address(1);
    }
}
